  'Cash on Delivery allows customers to pay in cash at the time of order delivery.' => 'Cash on Delivery allows customers to pay in cash at the time of order delivery.',
  'Digital Payment allows customers to pay online using integrated payment gateways. Supports cards, mobile banking, and digital wallets. Payment is completed before order confirmation.' => 'Digital Payment allows customers to pay online using integrated payment gateways. Supports cards, mobile banking, and digital wallets. Payment is completed before order confirmation.',
  'Offline Payment allows customers to place orders using manual payment methods. Supports bank transfer, mobile banking, or other manual methods. Customers must provide a payment reference or proof. Admin or vendor approval may be required before order confirmation.' => 'Offline Payment allows customers to place orders using manual payment methods. Supports bank transfer, mobile banking, or other manual methods. Customers must provide a payment reference or proof. Admin or vendor approval may be required before order confirmation.',
  'The Partial Payment feature allows customers to split an order payment into two parts. An initial amount is paid using the customer’s wallet balance, and the remaining amount can be paid using Cash on Delivery (COD), Digital Payment, or Offline Payment.This feature provides greater payment flexibility and helps customers place orders even when their wallet balance is insufficient for the full amount.' => 'The Partial Payment feature allows customers to split an order payment into two parts. An initial amount is paid using the customer’s wallet balance, and the remaining amount can be paid using Cash on Delivery (COD), Digital Payment, or Offline Payment.This feature provides greater payment flexibility and helps customers place orders even when their wallet balance is insufficient for the full amount.',
