  'Disbursement Guideline' => 'Disbursement Guideline',
  'Disbursement Setup' => 'Disbursement Setup',
  'The Disbursement Setup feature allows the admin to manage the payout of earnings to restaurants and delivery personnel. It ensures timely and accurate settlements based on completed orders, commissions, and deductions.' => 'The Disbursement Setup feature allows the admin to manage the payout of earnings to restaurants and delivery personnel. It ensures timely and accurate settlements based on completed orders, commissions, and deductions.',
  'The system supports two types of disbursement requests for restaurants and delivery personnel: Manual and Automated. These settings determine how earnings are transferred from the platform to the recipients.' => 'The system supports two types of disbursement requests for restaurants and delivery personnel: Manual and Automated. These settings determine how earnings are transferred from the platform to the recipients.',
  'Manual Disbursement' => 'Manual Disbursement',
  'Admin reviews and approves each payout request before processing.' => 'Admin reviews and approves each payout request before processing.',
  'Add this single line to your server crontab. Cron triggers schedule:run every minute and the app decides which scheduled tasks fire (disbursement, reminders, personalization).' => 'Add this single line to your server crontab. Cron triggers schedule:run every minute and the app decides which scheduled tasks fire (disbursement, reminders, personalization).',
  'Crontab Command' => 'Crontab Command',
  'Alternatively, if you can\'t install a crontab entry (Docker, some shared hosts), run this under a process manager such as Supervisor — it keeps schedule:work alive and invokes schedule:run every 60 seconds.' => 'Alternatively, if you can t install a crontab entry (Docker, some shared hosts), run this under a process manager such as Supervisor — it keeps schedule:work alive and invokes schedule:run every 60 seconds.',
  'Supervisor Command' => 'Supervisor Command',
  'Disbursement Scheduler Dependency' => 'Disbursement Scheduler Dependency',
  'When Automated Request is selected, Laravel\'s scheduler runs dm:disbursement and restaurant:disbursement based on the time period (daily / weekly / monthly) and create-time configured above. Pick ONE launcher for the scheduler.' => 'When Automated Request is selected, Laravel s scheduler runs dm:disbursement and restaurant:disbursement based on the time period (daily / weekly / monthly) and create-time configured above. Pick ONE launcher for the scheduler.',
  'Option 1 — Cron drives the scheduler' => 'Option 1 — Cron drives the scheduler',
  'Add this single line to your server crontab. Cron will trigger schedule:run every minute and Laravel decides which scheduled commands fire.' => 'Add this single line to your server crontab. Cron will trigger schedule:run every minute and Laravel decides which scheduled commands fire.',
  'Option 2 — Supervisor drives the scheduler (no cron)' => 'Option 2 — Supervisor drives the scheduler (no cron)',
  'Use this if you can\'t install a cron entry (Docker, some shared hosts). Supervisor keeps schedule:work alive; it internally invokes schedule:run every 60 seconds.' => 'Use this if you can t install a cron entry (Docker, some shared hosts). Supervisor keeps schedule:work alive  it internally invokes schedule:run every 60 seconds.',
  'Web Push VAPID Key' => 'Web Push VAPID Key',
  'Add this single crontab line on your server. The Laravel scheduler then sends every enabled reminder automatically at its configured interval (the same line also drives disbursement and personalization).' => 'Add this single crontab line on your server. The Laravel scheduler then sends every enabled reminder automatically at its configured interval (the same line also drives disbursement and personalization).',
